import Foundation

// MARK: - Vectors

public struct Vec3: Hashable, Sendable {
    public var x: Double, y: Double, z: Double
    public init(_ x: Double, _ y: Double, _ z: Double) { self.x = x; self.y = y; self.z = z }
    public static let zero = Vec3(0, 0, 0)

    public static func + (a: Vec3, b: Vec3) -> Vec3 { Vec3(a.x + b.x, a.y + b.y, a.z + b.z) }
    public static func - (a: Vec3, b: Vec3) -> Vec3 { Vec3(a.x - b.x, a.y - b.y, a.z - b.z) }
    public static func * (a: Vec3, k: Double) -> Vec3 { Vec3(a.x * k, a.y * k, a.z * k) }
    public static func += (a: inout Vec3, b: Vec3) { a = a + b }
    public func dot(_ b: Vec3) -> Double { x * b.x + y * b.y + z * b.z }
    public func cross(_ b: Vec3) -> Vec3 { Vec3(y * b.z - z * b.y, z * b.x - x * b.z, x * b.y - y * b.x) }
    public var length: Double { (x * x + y * y + z * z).squareRoot() }
    public var unit: Vec3 { let n = length; return n > 1e-12 ? self * (1 / n) : .zero }
    public func lerp(_ b: Vec3, _ f: Double) -> Vec3 { self + (b - self) * f }
}

extension Vec3: Codable {
    public init(from decoder: Decoder) throws {
        var c = try decoder.unkeyedContainer()
        self.init(try c.decode(Double.self), try c.decode(Double.self), try c.decode(Double.self))
    }
    public func encode(to encoder: Encoder) throws {
        var c = encoder.unkeyedContainer()
        try c.encode(x); try c.encode(y); try c.encode(z)
    }
}

// MARK: - Quaternions ([w, x, y, z])

public struct Quat: Hashable, Sendable {
    public var w: Double, x: Double, y: Double, z: Double
    public init(_ w: Double, _ x: Double, _ y: Double, _ z: Double) { self.w = w; self.x = x; self.y = y; self.z = z }
    public static let identity = Quat(1, 0, 0, 0)

    public static func * (a: Quat, b: Quat) -> Quat {
        Quat(a.w * b.w - a.x * b.x - a.y * b.y - a.z * b.z,
             a.w * b.x + a.x * b.w + a.y * b.z - a.z * b.y,
             a.w * b.y - a.x * b.z + a.y * b.w + a.z * b.x,
             a.w * b.z + a.x * b.y - a.y * b.x + a.z * b.w)
    }
    public var conjugate: Quat { Quat(w, -x, -y, -z) }
    public var normalized: Quat {
        let n = (w * w + x * x + y * y + z * z).squareRoot()
        return n > 0 ? Quat(w / n, x / n, y / n, z / n) : .identity
    }
    public func rotate(_ v: Vec3) -> Vec3 {
        let r = self * Quat(0, v.x, v.y, v.z) * conjugate
        return Vec3(r.x, r.y, r.z)
    }
    /// Axis * angle (radians).
    public var rotationVector: Vec3 {
        var q = self
        if q.w < 0 { q = Quat(-q.w, -q.x, -q.y, -q.z) }
        let s = (q.x * q.x + q.y * q.y + q.z * q.z).squareRoot()
        if s < 1e-9 { return Vec3(2 * q.x, 2 * q.y, 2 * q.z) }
        let k = 2 * atan2(s, q.w) / s
        return Vec3(q.x * k, q.y * k, q.z * k)
    }
    public init(rotationVector v: Vec3) {
        let angle = v.length
        if angle < 1e-12 { self = Quat(1, v.x / 2, v.y / 2, v.z / 2).normalized; return }
        let s = sin(angle / 2) / angle
        self.init(cos(angle / 2), v.x * s, v.y * s, v.z * s)
    }
    /// Normalized lerp with hemisphere fix — fine between consecutive samples.
    public func nlerp(_ b: Quat, _ f: Double) -> Quat {
        let sign: Double = (w * b.w + x * b.x + y * b.y + z * b.z) < 0 ? -1 : 1
        return Quat(w + (sign * b.w - w) * f, x + (sign * b.x - x) * f,
                    y + (sign * b.y - y) * f, z + (sign * b.z - z) * f).normalized
    }
}

extension Quat: Codable {
    public init(from decoder: Decoder) throws {
        var c = try decoder.unkeyedContainer()
        self.init(try c.decode(Double.self), try c.decode(Double.self), try c.decode(Double.self), try c.decode(Double.self))
    }
    public func encode(to encoder: Encoder) throws {
        var c = encoder.unkeyedContainer()
        try c.encode(w); try c.encode(x); try c.encode(y); try c.encode(z)
    }
}

// MARK: - 3x3 rotation matrices

public struct Mat3: Sendable {
    public var r0: Vec3, r1: Vec3, r2: Vec3
    public static let identity = Mat3(r0: Vec3(1, 0, 0), r1: Vec3(0, 1, 0), r2: Vec3(0, 0, 1))
    public static func * (m: Mat3, v: Vec3) -> Vec3 { Vec3(m.r0.dot(v), m.r1.dot(v), m.r2.dot(v)) }

    /// Rodrigues: rotation of |v| radians about v.
    public init(rotationVector v: Vec3) {
        let angle = v.length
        guard angle > 1e-12 else { self = .identity; return }
        let a = v * (1 / angle)
        let c = cos(angle), s = sin(angle), t = 1 - c
        r0 = Vec3(t * a.x * a.x + c, t * a.x * a.y - s * a.z, t * a.x * a.z + s * a.y)
        r1 = Vec3(t * a.x * a.y + s * a.z, t * a.y * a.y + c, t * a.y * a.z - s * a.x)
        r2 = Vec3(t * a.x * a.z - s * a.y, t * a.y * a.z + s * a.x, t * a.z * a.z + c)
    }
    public init(r0: Vec3, r1: Vec3, r2: Vec3) { self.r0 = r0; self.r1 = r1; self.r2 = r2 }

    /// Rotation that takes direction `from` onto direction `to`.
    public static func aligning(_ from: Vec3, to: Vec3) -> Mat3 {
        let f = from.unit, t = to.unit
        let axis = f.cross(t)
        let s = axis.length, c = f.dot(t)
        if s < 1e-9 {
            if c > 0 { return .identity }
            let perp = abs(f.x) < 0.9 ? f.cross(Vec3(1, 0, 0)).unit : f.cross(Vec3(0, 1, 0)).unit
            return Mat3(rotationVector: perp * Double.pi)
        }
        return Mat3(rotationVector: axis * (atan2(s, c) / s))
    }
}

// MARK: - Seeded RNG (reproducible augmentation and permutation tests)

public struct SeededRNG: RandomNumberGenerator, Sendable {
    private var state: UInt64
    public init(seed: UInt64) { state = seed &+ 0x9E37_79B9_7F4A_7C15 }
    public mutating func next() -> UInt64 {
        state &+= 0x9E37_79B9_7F4A_7C15
        var z = state
        z = (z ^ (z >> 30)) &* 0xBF58_476D_1CE4_E5B9
        z = (z ^ (z >> 27)) &* 0x94D0_49BB_1331_11EB
        return z ^ (z >> 31)
    }
    public mutating func uniform(_ lo: Double, _ hi: Double) -> Double { Double.random(in: lo...hi, using: &self) }
    public mutating func normal() -> Double {
        let u = max(Double.random(in: 0..<1, using: &self), 1e-12), v = Double.random(in: 0..<1, using: &self)
        return (-2 * log(u)).squareRoot() * cos(2 * .pi * v)
    }
    public mutating func unitVector() -> Vec3 { Vec3(normal(), normal(), normal()).unit }
}

/// Stable FNV-1a hash (Swift's `hashValue` is randomized per process).
public func stableHash(_ s: String) -> UInt64 {
    var h: UInt64 = 0xcbf2_9ce4_8422_2325
    for b in s.utf8 { h ^= UInt64(b); h = h &* 0x100_0000_01b3 }
    return h
}

public func median(_ values: [Double]) -> Double {
    guard !values.isEmpty else { return 0 }
    let s = values.sorted()
    return s[s.count / 2]
}

import Foundation

/// Which earbud produced the motion data (CMDeviceMotion.sensorLocation).
public enum SensorLocation: String, Codable, Sendable {
    case unknown, left, right
}

/// One headphone-motion reading, independent of CoreMotion so the core stays testable.
public struct MotionSample: Codable, Hashable, Sendable {
    /// Seconds (device timestamp; any monotonic clock).
    public var t: Double
    /// User acceleration in g, gravity removed, device frame.
    public var accel: Vec3
    /// Rotation rate in rad/s, device frame.
    public var rotation: Vec3
    /// Gravity in g, device frame.
    public var gravity: Vec3
    /// Attitude quaternion.
    public var attitude: Quat
    /// Euler attitude in radians (used for nod/shake detection).
    public var pitch: Double, roll: Double, yaw: Double
    public var location: SensorLocation

    public init(t: Double, accel: Vec3 = .zero, rotation: Vec3 = .zero, gravity: Vec3 = Vec3(0, 0, -1),
                attitude: Quat = .identity, pitch: Double = 0, roll: Double = 0, yaw: Double = 0,
                location: SensorLocation = .unknown) {
        self.t = t; self.accel = accel; self.rotation = rotation; self.gravity = gravity
        self.attitude = attitude; self.pitch = pitch; self.roll = roll; self.yaw = yaw; self.location = location
    }

    enum CodingKeys: String, CodingKey { case t, a, r, g, q, p, l }

    // Compact keys: datasets hold thousands of samples.
    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        t = try c.decode(Double.self, forKey: .t)
        accel = try c.decode(Vec3.self, forKey: .a)
        rotation = try c.decode(Vec3.self, forKey: .r)
        gravity = try c.decode(Vec3.self, forKey: .g)
        attitude = try c.decode(Quat.self, forKey: .q)
        let e = try c.decode(Vec3.self, forKey: .p)
        pitch = e.x; roll = e.y; yaw = e.z
        location = try c.decodeIfPresent(SensorLocation.self, forKey: .l) ?? .unknown
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        try c.encode(t, forKey: .t)
        try c.encode(accel, forKey: .a)
        try c.encode(rotation, forKey: .r)
        try c.encode(gravity, forKey: .g)
        try c.encode(attitude, forKey: .q)
        try c.encode(Vec3(pitch, roll, yaw), forKey: .p)
        try c.encode(location, forKey: .l)
    }
}

import Foundation

public enum Signal {
    public struct Resampled: Sendable {
        public var samples: [MotionSample]
        /// Largest gap between consecutive raw samples, in seconds.
        public var maxGap: Double
    }

    /// Interpolate onto a uniform grid at `rate` Hz (D6). Bluetooth jitter and drops otherwise
    /// look like the word was said faster or slower.
    public static func resample(_ raw: [MotionSample], rate: Double = 25) -> Resampled {
        let input = raw.sorted { $0.t < $1.t }
        guard let first = input.first, let last = input.last, input.count >= 2, last.t > first.t else {
            return Resampled(samples: input, maxGap: 0)
        }
        var maxGap = 0.0
        for i in 1..<input.count { maxGap = max(maxGap, input[i].t - input[i - 1].t) }

        let count = Int(((last.t - first.t) * rate).rounded(.down)) + 1
        var out: [MotionSample] = []
        out.reserveCapacity(count)
        var j = 0
        for k in 0..<count {
            let t = first.t + Double(k) / rate
            while j + 1 < input.count - 1, input[j + 1].t < t { j += 1 }
            let a = input[j], b = input[min(j + 1, input.count - 1)]
            let span = b.t - a.t
            let f = span > 0 ? min(max((t - a.t) / span, 0), 1) : 0
            out.append(MotionSample(
                t: t,
                accel: a.accel.lerp(b.accel, f),
                rotation: a.rotation.lerp(b.rotation, f),
                gravity: a.gravity.lerp(b.gravity, f),
                attitude: a.attitude.nlerp(b.attitude, f),
                pitch: a.pitch + (b.pitch - a.pitch) * f,
                roll: a.roll + (b.roll - a.roll) * f,
                yaw: a.yaw + remainder(b.yaw - a.yaw, 2 * .pi) * f,
                location: a.location))
        }
        return Resampled(samples: out, maxGap: maxGap)
    }

    /// 2nd-order Butterworth high-pass coefficients (RBJ cookbook, Q = 1/√2).
    struct Biquad {
        var b0, b1, b2, a1, a2: Double
        init(highPass cutoff: Double, rate: Double) {
            let w0 = 2 * Double.pi * cutoff / rate
            let alpha = sin(w0) / (2 * (0.5).squareRoot())
            let c = cos(w0)
            let a0 = 1 + alpha
            b0 = (1 + c) / 2 / a0
            b1 = -(1 + c) / a0
            b2 = (1 + c) / 2 / a0
            a1 = -2 * c / a0
            a2 = (1 - alpha) / a0
        }
        func run(_ x: [Double]) -> [Double] {
            guard let x0 = x.first else { return [] }
            var y = [Double](repeating: 0, count: x.count)
            // Start in steady state for a constant input (high-pass output of DC is 0).
            var x1 = x0, x2 = x0, y1 = 0.0, y2 = 0.0
            for i in x.indices {
                let v = b0 * x[i] + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2
                x2 = x1; x1 = x[i]; y2 = y1; y1 = v
                y[i] = v
            }
            return y
        }
    }

    /// Zero-phase high-pass (forward + backward) with odd reflection padding (D8).
    public static func highPass(_ x: [Double], cutoff: Double, rate: Double) -> [Double] {
        let n = x.count
        guard n >= 4, cutoff > 0 else { return x }
        let pad = min(n - 1, Int(rate * 1.0))
        var padded: [Double] = []
        padded.reserveCapacity(n + 2 * pad)
        for i in stride(from: pad, through: 1, by: -1) { padded.append(2 * x[0] - x[i]) }
        padded.append(contentsOf: x)
        for i in 1...pad { padded.append(2 * x[n - 1] - x[n - 1 - i]) }
        let filter = Biquad(highPass: cutoff, rate: rate)
        let forward = filter.run(padded)
        let backward = filter.run(forward.reversed())
        return Array(backward.reversed()[pad..<(pad + n)])
    }
}

import Foundation

/// A multichannel feature sequence stored flat (frame-major) for fast DTW.
public struct FeatureSequence: Sendable, Hashable {
    public var values: [Double]
    public let dims: Int
    public var count: Int { dims == 0 ? 0 : values.count / dims }

    public init(values: [Double], dims: Int) { self.values = values; self.dims = dims }
    public init(frames: [[Double]]) {
        dims = frames.first?.count ?? 0
        values = frames.flatMap { $0 }
    }
    public subscript(frame i: Int, dim d: Int) -> Double {
        get { values[i * dims + d] }
        set { values[i * dims + d] = newValue }
    }
    public func channel(_ d: Int) -> [Double] { (0..<count).map { values[$0 * dims + d] } }
}

public struct FeatureConfig: Sendable, Hashable {
    public var rate: Double = 25
    public var highPassHz: Double = 0.8
    /// Rest pre-roll used to measure gravity for re-seat canonicalisation (D7).
    public var restSeconds: Double = 0.3
    public var trim: Bool = true
    public var trimPadding: Int = 2
    public init() {}
}

/// What the pipeline produces for one captured segment.
public struct SegmentFeatures: Sendable {
    /// 9 channels per frame: accel xyz, rotation-rate xyz, attitude-change rotation vector xyz,
    /// all in the gravity-canonical frame and high-passed.
    public var sequence: FeatureSequence
    /// Per-frame activity before trimming.
    public var energies: [Double]
    public var energyPeak: Double
    public var maxGap: Double
    /// Largest head rotation from the segment start, before filtering (degrees).
    public var headRotationDegrees: Double
    public var location: SensorLocation
}

public enum Features {
    public static let dims = 9

    /// Activity score: rotation (rad/s) and acceleration (g) on comparable scales.
    public static func energy(_ seq: FeatureSequence, frame i: Int) -> Double {
        let r = (pow(seq[frame: i, dim: 3], 2) + pow(seq[frame: i, dim: 4], 2) + pow(seq[frame: i, dim: 5], 2)).squareRoot()
        let a = (pow(seq[frame: i, dim: 0], 2) + pow(seq[frame: i, dim: 1], 2) + pow(seq[frame: i, dim: 2], 2)).squareRoot()
        return r + 5 * a
    }

    public static func extract(_ raw: [MotionSample], config: FeatureConfig = FeatureConfig()) -> SegmentFeatures? {
        let resampled = Signal.resample(raw, rate: config.rate)
        let s = resampled.samples
        guard s.count >= 6 else { return nil }

        // D7: rotate so rest gravity points down; removes earbud seating and head posture.
        let restCount = max(1, min(s.count, Int(config.restSeconds * config.rate)))
        var g = Vec3.zero
        for i in 0..<restCount { g += s[i].gravity }
        let canonical = Mat3.aligning(g, to: Vec3(0, 0, -1))
        let q0 = s[0].attitude

        var channels = [[Double]](repeating: [], count: dims)
        var headDegrees = 0.0
        for sample in s {
            let a = canonical * sample.accel
            let r = canonical * sample.rotation
            let rel = (q0.conjugate * sample.attitude).rotationVector
            headDegrees = max(headDegrees, rel.length * 180 / .pi)
            let v = canonical * rel
            for (d, value) in [a.x, a.y, a.z, r.x, r.y, r.z, v.x, v.y, v.z].enumerated() { channels[d].append(value) }
        }

        // D8: remove drift and slow head movement.
        channels = channels.map { Signal.highPass($0, cutoff: config.highPassHz, rate: config.rate) }

        var frames: [[Double]] = (0..<s.count).map { i in channels.map { $0[i] } }
        let full = FeatureSequence(frames: frames)
        let energies = (0..<full.count).map { energy(full, frame: $0) }

        if config.trim, let range = activeRange(energies, padding: config.trimPadding) {
            frames = Array(frames[range])
        }
        return SegmentFeatures(
            sequence: FeatureSequence(frames: frames),
            energies: energies,
            energyPeak: energies.max() ?? 0,
            maxGap: resampled.maxGap,
            headRotationDegrees: headDegrees,
            location: s[0].location)
    }

    /// Frames above a segment-relative threshold, so training and decoding trim the same way.
    static func activeRange(_ energies: [Double], padding: Int) -> ClosedRange<Int>? {
        guard energies.count > 8 else { return nil }
        let sorted = energies.sorted()
        let floor = sorted[sorted.count / 5], peak = sorted[sorted.count - 1]
        guard peak > floor * 1.5 else { return nil }
        let threshold = floor + 0.15 * (peak - floor)
        guard let first = energies.firstIndex(where: { $0 > threshold }),
              let last = energies.lastIndex(where: { $0 > threshold }) else { return nil }
        let lo = max(0, first - padding), hi = min(energies.count - 1, last + padding)
        return hi - lo + 1 >= 6 ? lo...hi : nil
    }

    /// Per-channel standard deviation over a set of sequences (the training fold only, D12).
    public static func channelScales(_ seqs: [FeatureSequence]) -> [Double] {
        let dims = seqs.first?.dims ?? Features.dims
        var sum = [Double](repeating: 0, count: dims), sq = sum
        var n = 0.0
        for seq in seqs {
            for i in 0..<seq.count {
                for d in 0..<dims { let v = seq[frame: i, dim: d]; sum[d] += v; sq[d] += v * v }
                n += 1
            }
        }
        guard n > 1 else { return [Double](repeating: 1, count: dims) }
        return (0..<dims).map { d in max((sq[d] / n - pow(sum[d] / n, 2)).squareRoot(), 1e-6) }
    }

    public static func scaled(_ seq: FeatureSequence, by scales: [Double]) -> FeatureSequence {
        var out = seq
        for i in 0..<seq.count { for d in 0..<seq.dims { out[frame: i, dim: d] /= scales[d] } }
        return out
    }

    /// Median per-frame energy of a still recording: the noise floor for the quality gate.
    public static func noiseFloor(_ rest: [MotionSample], config: FeatureConfig = FeatureConfig()) -> Double? {
        var c = config; c.trim = false
        guard let f = extract(rest, config: c) else { return nil }
        return max(median(f.energies), 1e-4)
    }
}

import Foundation

/// Dependent multivariate DTW with a Sakoe–Chiba band and early abandoning (D10).
public enum DTW {
    /// Normalized distance (total path cost / (n + m)). Returns `.infinity` once it can no
    /// longer beat `cutoff`, which skips most of the work for hopeless references.
    public static func distance(_ a: FeatureSequence, _ b: FeatureSequence,
                                band bandFraction: Double = 0.2, cutoff: Double = .infinity) -> Double {
        let n = a.count, m = b.count, dims = a.dims
        guard n > 0, m > 0, dims == b.dims else { return .infinity }
        let band = max(abs(n - m), Int(Double(max(n, m)) * bandFraction))
        let limit = cutoff.isFinite ? cutoff * Double(n + m) : .infinity

        var previous = [Double](repeating: .infinity, count: m + 1)
        var current = previous
        previous[0] = 0

        return a.values.withUnsafeBufferPointer { av in
            b.values.withUnsafeBufferPointer { bv in
                for i in 1...n {
                    for j in 0...m { current[j] = .infinity }
                    let lo = max(1, i - band), hi = min(m, i + band)
                    var rowMin = Double.infinity
                    if lo <= hi {
                        let ai = (i - 1) * dims
                        for j in lo...hi {
                            let bj = (j - 1) * dims
                            var sum = 0.0
                            for d in 0..<dims { let diff = av[ai + d] - bv[bj + d]; sum += diff * diff }
                            let best = min(previous[j], current[j - 1], previous[j - 1])
                            let value = sum.squareRoot() + best
                            current[j] = value
                            if value < rowMin { rowMin = value }
                        }
                    }
                    if rowMin > limit { return .infinity }
                    swap(&previous, &current)
                }
                return previous[m] / Double(n + m)
            }
        }
    }
}

import Foundation

/// Feature-level augmentation (D9): rotation simulates re-seating, time-warp simulates speaking
/// rate, scaling simulates effort. Only ever applied to training data.
public struct AugmentConfig: Sendable, Hashable {
    public var maxRotationDegrees: Double = 12
    public var warp: ClosedRange<Double> = 0.85...1.15
    public var amplitude: ClosedRange<Double> = 0.9...1.1
    /// Jitter as a fraction of each channel's spread in this sequence.
    public var jitter: Double = 0.03
    public init() {}
}

public enum Augment {
    public static func augment(_ seq: FeatureSequence, config: AugmentConfig = AugmentConfig(),
                               rng: inout SeededRNG) -> FeatureSequence {
        guard seq.count >= 2, seq.dims % 3 == 0 else { return seq }
        let angle = rng.uniform(-config.maxRotationDegrees, config.maxRotationDegrees) * .pi / 180
        let rotation = Mat3(rotationVector: rng.unitVector() * angle)
        let gain = rng.uniform(config.amplitude.lowerBound, config.amplitude.upperBound)
        let warp = rng.uniform(config.warp.lowerBound, config.warp.upperBound)

        // Rotate each xyz triplet, scale.
        var rotated = seq
        for i in 0..<seq.count {
            for g in stride(from: 0, to: seq.dims, by: 3) {
                let v = rotation * Vec3(seq[frame: i, dim: g], seq[frame: i, dim: g + 1], seq[frame: i, dim: g + 2])
                rotated[frame: i, dim: g] = v.x * gain
                rotated[frame: i, dim: g + 1] = v.y * gain
                rotated[frame: i, dim: g + 2] = v.z * gain
            }
        }

        // Time-warp by linear resampling.
        let newCount = max(4, Int((Double(seq.count) * warp).rounded()))
        var values = [Double](repeating: 0, count: newCount * seq.dims)
        for k in 0..<newCount {
            let pos = Double(k) * Double(seq.count - 1) / Double(newCount - 1)
            let i = min(Int(pos), seq.count - 2), f = pos - Double(i)
            for d in 0..<seq.dims {
                values[k * seq.dims + d] = rotated[frame: i, dim: d] * (1 - f) + rotated[frame: i + 1, dim: d] * f
            }
        }
        var out = FeatureSequence(values: values, dims: seq.dims)

        // Jitter relative to each channel's spread.
        if config.jitter > 0 {
            for d in 0..<seq.dims {
                let ch = out.channel(d)
                let mean = ch.reduce(0, +) / Double(ch.count)
                let sd = (ch.map { pow($0 - mean, 2) }.reduce(0, +) / Double(ch.count)).squareRoot()
                for i in 0..<out.count { out[frame: i, dim: d] += rng.normal() * sd * config.jitter }
            }
        }
        return out
    }
}

