/// Synthetic AirPods motion (D17). Words get a deterministic signature from their syllables and
/// how open the vowels are; each take varies in tempo, amplitude and onset; re-seating rotates the
/// sensor. **Accuracy on simulated data proves nothing about real AirPods** — it exists to
/// exercise the pipeline and the UI without hardware.
public final class MotionSimulator: @unchecked Sendable {
    public let rate: Double
    public private(set) var time: Double = 0
    public var location: SensorLocation = .left
    /// Probability that a given sample is dropped (Bluetooth loss).
    public var dropProbability: Double = 0.01

    private var rng: SeededRNG
    private var head = Quat.identity
    private var seat: Quat
    private var events: [Event] = []
    private let lock = NSLock()

    /// Head-frame angular velocity (rad/s) and acceleration (g) as a function of time since start.
    private struct Event {
        var start: Double
        var duration: Double
        var motion: (Double) -> (omega: Vec3, accel: Vec3)
    }

    public init(seed: UInt64 = 42, rate: Double = 25) {
        self.rate = rate
        rng = SeededRNG(seed: seed)
        seat = Quat.identity
        reseat()
    }

    /// Take the earbuds out and put them back: a new random sensor orientation (±15°).
    public func reseat() {
        lock.lock(); defer { lock.unlock() }
        let angle = rng.uniform(-15, 15) * .pi / 180
        seat = Quat(rotationVector: rng.unitVector() * angle)
    }

    /// Start a movement now (plus a human-like onset delay for words).
    public func perform(_ action: SimAction) {
        lock.lock(); defer { lock.unlock() }
        events.append(contentsOf: Self.events(for: action, at: time, rng: &rng))
    }

    /// Advance one sample period. Returns nil when the sample is "dropped".
    public func step() -> MotionSample? {
        lock.lock(); defer { lock.unlock() }
        let dt = 1 / rate
        time += dt

        var omega = Vec3(rng.normal() * 0.012, rng.normal() * 0.012, rng.normal() * 0.012)
        var accel = Vec3(rng.normal() * 0.004, rng.normal() * 0.004, rng.normal() * 0.004)
        // Slow postural sway (removed by the high-pass).
        omega += Vec3(0.02 * sin(time * 0.7), 0.01 * sin(time * 0.4), 0.015 * sin(time * 0.3))
        events.removeAll { time > $0.start + $0.duration }
        for e in events where time >= e.start {
            let m = e.motion(time - e.start)
            omega += m.omega; accel += m.accel
        }

        head = (head * Quat(rotationVector: omega * dt)).normalized
        let device = (head * seat).normalized
        let toDevice = seat.conjugate
        let rv = head.rotationVector
        let sample = MotionSample(
            t: time + rng.normal() * 0.002,
            accel: toDevice.rotate(accel),
            rotation: toDevice.rotate(omega),
            gravity: device.conjugate.rotate(Vec3(0, 0, -1)),
            attitude: device,
            pitch: rv.x, roll: rv.y, yaw: rv.z,
            location: location)
        return rng.uniform(0, 1) < dropProbability ? nil : sample
    }

    /// Record a whole capture window the way the app does: rest pre-roll, then the movement.
    public func recordTake(_ action: SimAction?, preroll: Double = 0.3, window: Double = 1.8) -> [MotionSample] {
        var out: [MotionSample] = []
        for _ in 0..<Int(preroll * rate) { if let s = step() { out.append(s) } }
        if let action { perform(action) }
        for _ in 0..<Int(window * rate) { if let s = step() { out.append(s) } }
        return out
    }

    // MARK: Movement models

    private static func events(for action: SimAction, at now: Double, rng: inout SeededRNG) -> [Event] {
        switch action {
        case .word(let word): return wordEvents(word, at: now, rng: &rng)
        case .nod: return [oscillation(axis: Vec3(1, 0, 0), degrees: 14, cycles: 1, duration: 0.8, at: now)]
        case .shake: return [oscillation(axis: Vec3(0, 0, 1), degrees: 18, cycles: 1, duration: 0.9, at: now)]
        case .noise(let kind):
            let onset = now + rng.uniform(0.15, 0.35)
            switch kind {
            case .chew:
                return (0..<4).map { i in bump(axis: Vec3(0.4, 0.2, 0.9).unit, peak: 0.35, accel: Vec3(0, 0.01, 0.02),
                                              duration: 0.32, at: onset + Double(i) * 0.38) }
            case .swallow:
                return [bump(axis: Vec3(1, 0, 0), peak: 0.25, accel: Vec3(0, 0.02, -0.01), duration: 0.7, at: onset)]
            case .turn:
                return [oscillation(axis: Vec3(0, 0, 1), degrees: 30, cycles: 0.5, duration: 1.2, at: onset)]
            case .nod:
                return [oscillation(axis: Vec3(1, 0, 0), degrees: 14, cycles: 1, duration: 0.8, at: onset)]
            case .smile:
                return [bump(axis: Vec3(0, 1, 0.3).unit, peak: 0.12, accel: Vec3(0.015, 0, 0.01), duration: 0.9, at: onset)]
            case .lookUp:
                return [oscillation(axis: Vec3(-1, 0, 0), degrees: 20, cycles: 0.5, duration: 1.1, at: onset)]
            }
        }
    }

    /// Syllables from vowel groups; bump size from how open the vowel is.
    static func syllables(_ word: String) -> [Double] {
        let openness: [Character: Double] = ["a": 1.0, "o": 0.85, "e": 0.6, "u": 0.5, "i": 0.45, "y": 0.45]
        var result: [Double] = []
        var inVowel = false
        for ch in word.lowercased() {
            if let o = openness[ch] {
                if inVowel { result[result.count - 1] = max(result[result.count - 1], o) } else { result.append(o) }
                inVowel = true
            } else {
                inVowel = false
            }
        }
        // Silent final "e" ("stope" style) — drop it when there's another syllable.
        if result.count > 1, word.lowercased().hasSuffix("e"), !word.lowercased().hasSuffix("ee") { result.removeLast() }
        return result.isEmpty ? [0.5] : result
    }

    private static func wordEvents(_ word: String, at now: Double, rng: inout SeededRNG) -> [Event] {
        var sig = SeededRNG(seed: stableHash(word))
        // Per-word articulation: mostly a pitch-axis jaw rotation, with a word-specific mix.
        let axis = Vec3(1, sig.uniform(-0.35, 0.35), sig.uniform(-0.25, 0.25)).unit
        let syllableBase = sig.uniform(0.2, 0.28)
        let tempo = rng.uniform(0.87, 1.13), gain = rng.uniform(0.85, 1.15)
        var t = now + rng.uniform(0.15, 0.4)
        var out: [Event] = []
        for open in syllables(word) {
            let d = syllableBase * (0.75 + 0.5 * open) * tempo
            out.append(bump(axis: axis, peak: 0.32 * open * gain, accel: Vec3(0, 0.012, 0.018) * (open * gain),
                            duration: d, at: t))
            t += d + 0.04 * tempo
        }
        return out
    }

    /// Open-then-close movement: angular velocity is the derivative of a raised cosine.
    private static func bump(axis: Vec3, peak: Double, accel: Vec3, duration: Double, at start: Double) -> Event {
        Event(start: start, duration: duration) { tau in
            let phase = 2 * Double.pi * tau / duration
            let v = sin(phase)
            return (axis * (peak * v), accel * cos(phase))
        }
    }

    /// Head rotation of `degrees` peak that goes out and comes back over `cycles`.
    private static func oscillation(axis: Vec3, degrees: Double, cycles: Double, duration: Double, at start: Double) -> Event {
        let amplitude = degrees * .pi / 180
        return Event(start: start, duration: duration) { tau in
            // angle(t) = A·sin²(π·c·t/D) for half-cycles, A·sin(2π·c·t/D) for full cycles.
            let w = 2 * Double.pi * cycles / duration
            let rate = cycles == 0.5 ? amplitude * (Double.pi / duration) * sin(2 * Double.pi * tau / duration)
                                     : amplitude * w * cos(w * tau)
            return (axis * rate, .zero)
        }
    }
}

import Foundation

/// M1 acceptance checks. Defined in the library so they run both under `swift test` and under
/// `swift run LouVoiceCheck` (Command Line Tools have no XCTest).
public enum SelfTests {
    public struct Failure: Error, CustomStringConvertible { public let description: String }

    static func expect(_ condition: Bool, _ message: @autoclosure () -> String) throws {
        if !condition { throw Failure(description: message()) }
    }

    public static let all: [(name: String, run: () throws -> Void)] = [
        ("resampling makes a uniform grid and reports gaps", resampling),
        ("high-pass removes DC and drift, keeps jaw-band motion", highPass),
        ("re-seat rotation is undone by gravity canonicalisation", reseatCanonicalisation),
        ("DTW: identical is 0 and tolerates time-warp", dtw),
        ("classifier separates simulated words", classifier),
        ("evaluation: p < 0.01 with signal, p > 0.05 on noise", evaluation),
        ("nod and shake are detected, mouthing is not", gestures),
        ("quality gate rejects head movement and weak takes", quality),
        ("dataset samples round-trip through JSON", codable),
    ]

    static func resampling() throws {
        var raw: [MotionSample] = []
        var t = 0.0
        for i in 0..<60 {
            if i == 30 { t += 0.2 }                      // a dropout
            raw.append(MotionSample(t: t, accel: Vec3(t, 0, 0)))
            t += 0.04 + (i % 3 == 0 ? 0.004 : -0.002)    // jitter
        }
        let r = Signal.resample(raw, rate: 25)
        for i in 1..<r.samples.count {
            try expect(abs(r.samples[i].t - r.samples[i - 1].t - 0.04) < 1e-9, "grid not uniform at \(i)")
        }
        try expect(r.maxGap > 0.2, "gap not reported: \(r.maxGap)")
        // Linear signal survives interpolation exactly.
        for s in r.samples { try expect(abs(s.accel.x - s.t) < 1e-9, "interpolation wrong at t=\(s.t)") }
    }

    static func highPass() throws {
        let rate = 25.0
        let n = 75
        let drift = (0..<n).map { 0.5 + 0.02 * Double($0) }                         // DC + slow ramp
        let jaw = (0..<n).map { 0.1 * sin(2 * .pi * 4 * Double($0) / rate) }        // 4 Hz
        let out = Signal.highPass(zip(drift, jaw).map(+), cutoff: 0.8, rate: rate)
        let mid = 15..<(n - 15)
        let residual = mid.map { abs(out[$0] - jaw[$0]) }.max()!
        try expect(residual < 0.03, "high-pass residual too large: \(residual)")
        let flat = Signal.highPass([Double](repeating: 3, count: 50), cutoff: 0.8, rate: rate)
        try expect(flat.allSatisfy { abs($0) < 1e-9 }, "DC not removed")
    }

    static func reseatCanonicalisation() throws {
        // Same take recorded with two different seatings must give near-identical features.
        let a = MotionSimulator(seed: 5), b = MotionSimulator(seed: 5)
        a.dropProbability = 0; b.dropProbability = 0
        b.reseat(); b.reseat()                                       // different orientation, same motion stream after
        let sa = a.recordTake(.word("banana")), sb = b.recordTake(.word("banana"))
        var cfg = FeatureConfig(); cfg.trim = false
        let fa = Features.extract(sa, config: cfg)!, fb = Features.extract(sb, config: cfg)!

        // Raw device-frame rotation differs because of the seat; canonical features should be closer.
        func rms(_ x: [Double], _ y: [Double]) -> Double {
            (zip(x, y).map { pow($0 - $1, 2) }.reduce(0, +) / Double(x.count)).squareRoot()
        }
        let rawA = sa.map(\.gravity.x), rawB = sb.map(\.gravity.x)
        try expect(rms(rawA, rawB) > 0.02, "test setup: seats should differ")
        let n = min(fa.sequence.count, fb.sequence.count)
        let pitchA = Array(fa.sequence.channel(3).prefix(n)), pitchB = Array(fb.sequence.channel(3).prefix(n))
        let energy = (pitchA.map { $0 * $0 }.reduce(0, +) / Double(n)).squareRoot()
        try expect(rms(pitchA, pitchB) < 0.35 * energy, "canonical features still differ: \(rms(pitchA, pitchB)) vs \(energy)")
    }

    static func dtw() throws {
        func seq(_ n: Int, freq: Double, phase: Double = 0) -> FeatureSequence {
            FeatureSequence(frames: (0..<n).map { i in
                let x = sin(2 * .pi * freq * Double(i) / Double(n) + phase)
                return [x, 0.5 * x, 0, 0, 0, 0, 0, 0, 0]
            })
        }
        let a = seq(40, freq: 2), stretched = seq(52, freq: 2), other = seq(40, freq: 3, phase: 1)
        try expect(DTW.distance(a, a) == 0, "identical not 0")
        try expect(DTW.distance(a, stretched) < DTW.distance(a, other) * 0.5, "not warp tolerant")
        let exact = DTW.distance(a, other)
        try expect(DTW.distance(a, other, cutoff: exact * 0.1) == .infinity, "early abandon didn't trigger")
        try expect(abs(DTW.distance(a, other, cutoff: exact * 2) - exact) < 1e-12, "early abandon changed result")
    }

    static func simulatedTakes(words: [String], reps: Int, blocks: Int, noise: Bool, seed: UInt64) -> [EvalTake] {
        let sim = MotionSimulator(seed: seed)
        var takes: [EvalTake] = []
        var rng = SeededRNG(seed: seed)
        for b in 0..<blocks {
            sim.reseat()
            var prompts: [SimAction] = words.flatMap { w in Array(repeating: SimAction.word(w), count: reps) }
            if noise { prompts += NoiseKind.allCases.prefix(4).map { SimAction.noise($0) } }
            for action in prompts.shuffled(using: &rng) {
                let samples = sim.recordTake(action)
                guard let f = Features.extract(samples) else { continue }
                let label: String
                switch action { case .word(let w): label = w; default: label = noneLabel }
                takes.append(EvalTake(id: UUID().uuidString, label: label, block: "b\(b)", features: f.sequence))
            }
        }
        return takes
    }

    static func classifier() throws {
        let words = ["yes", "banana", "hello", "stop"]
        let train = simulatedTakes(words: words, reps: 4, blocks: 2, noise: true, seed: 11)
        guard let c = Classifier(training: train.map { LabeledFeatures(id: $0.id, label: $0.label, features: $0.features) }) else {
            throw Failure(description: "classifier not built")
        }
        let test = simulatedTakes(words: words, reps: 2, blocks: 1, noise: false, seed: 99)
        let correct = test.filter { c.predict($0.features).best?.label == $0.label }.count
        try expect(Double(correct) / Double(test.count) >= 0.75, "only \(correct)/\(test.count) correct")
        // Active-word filter never returns an inactive word.
        let p = c.predict(test[0].features, active: ["yes", "stop"])
        try expect(p.ranked.allSatisfy { ["yes", "stop", noneLabel].contains($0.label) }, "active filter leaked")
    }

    static func evaluation() throws {
        let real = simulatedTakes(words: ["yes", "banana", "hello"], reps: 3, blocks: 3, noise: false, seed: 3)
        guard let signal = Evaluation.run(real, permutations: 100) else { throw Failure(description: "no report") }
        try expect(signal.mode == .leaveBlockOut, "should hold out blocks")
        try expect(signal.pValue < 0.01, "signal p = \(signal.pValue), acc \(signal.accuracy)")

        // Same takes, labels assigned at random: there is nothing to learn.
        var rng = SeededRNG(seed: 4)
        let labels = ["a", "b", "c"]
        let null = real.map { t -> EvalTake in var t = t; t.label = labels.randomElement(using: &rng)!; return t }
        guard let noise = Evaluation.run(null, permutations: 100) else { throw Failure(description: "no null report") }
        try expect(noise.pValue > 0.05, "noise p = \(noise.pValue)")
    }

    static func gestures() throws {
        func detect(_ action: SimAction) -> HeadGesture? {
            let sim = MotionSimulator(seed: 8); sim.dropProbability = 0
            var detector = HeadGestureDetector()
            var found: HeadGesture?
            for s in sim.recordTake(action, window: 2.0) { if let g = detector.push(s) { found = found ?? g } }
            return found
        }
        try expect(detect(.nod) == .nod, "nod not detected (got \(String(describing: detect(.nod))))")
        try expect(detect(.shake) == .shake, "shake not detected (got \(String(describing: detect(.shake))))")
        try expect(detect(.word("banana")) == nil, "mouthing detected as a gesture")
    }

    static func quality() throws {
        let sim = MotionSimulator(seed: 2); sim.dropProbability = 0
        let floor = Features.noiseFloor(sim.recordTake(nil, preroll: 0, window: 2))
        let word = Features.extract(sim.recordTake(.word("banana")))!
        try expect(Quality.check(word, noiseFloor: floor, isNone: false) == nil, "good take rejected")
        let turn = Features.extract(sim.recordTake(.noise(.turn)))!
        try expect(Quality.check(turn, noiseFloor: floor, isNone: false) != nil, "head turn accepted as a word take")
        try expect(Quality.check(turn, noiseFloor: floor, isNone: true) == nil, "head turn rejected as a noise take")
        let still = Features.extract(sim.recordTake(nil))!
        try expect(Quality.check(still, noiseFloor: floor, isNone: false) != nil, "still take accepted")
    }

    static func codable() throws {
        let s = MotionSample(t: 1.5, accel: Vec3(1, 2, 3), rotation: Vec3(4, 5, 6), gravity: Vec3(0, 0, -1),
                             attitude: Quat(1, 0, 0, 0), pitch: 0.1, roll: 0.2, yaw: 0.3, location: .right)
        let back = try JSONDecoder().decode(MotionSample.self, from: JSONEncoder().encode(s))
        try expect(back == s, "round trip changed the sample")
    }

    /// Runs everything, printing one line per check. Returns the failure count.
    @discardableResult
    public static func runAll(log: (String) -> Void = { print($0) }) -> Int {
        var failures = 0
        for test in all {
            let start = Date()
            do {
                try test.run()
                log(String(format: "PASS  %@  (%.2fs)", test.name, Date().timeIntervalSince(start)))
            } catch {
                failures += 1
                log("FAIL  \(test.name): \(error)")
            }
        }
        log(failures == 0 ? "All \(all.count) checks passed." : "\(failures) of \(all.count) checks failed.")
        return failures
    }
}

