import CoreMotion
import Foundation
import LouVoiceCore
import Observation

/// Single source of motion samples for the app: real AirPods (CoreMotion) or the simulator.
/// Keeps a short history for plots and pre-roll, and serves timed capture windows (D13).
@MainActor @Observable
final class MotionHub {
    enum Source: String, CaseIterable, Identifiable {
        case airpods = "AirPods"
        case simulator = "Simulator"
        var id: String { rawValue }
    }

    enum Status: Equatable {
        case idle, unsupported, denied, waiting, streaming, error(String)
        var label: String {
            switch self {
            case .idle: "Stopped"
            case .unsupported: "Headphone motion not supported on this Mac"
            case .denied: "Motion access denied — System Settings › Privacy & Security › Motion & Fitness"
            case .waiting: "Waiting for AirPods (put them in, connected to this Mac)"
            case .streaming: "Streaming"
            case .error(let message): message
            }
        }
    }

    static let historySeconds = 10.0

    var source: Source = .airpods {
        didSet { if source != oldValue { restart() } }
    }
    private(set) var status: Status = .idle
    private(set) var latest: MotionSample?
    private(set) var history: [MotionSample] = []
    private(set) var sampleRate: Double = 0
    private(set) var maxRecentGap: Double = 0

    /// Called for every sample (gesture detection).
    @ObservationIgnored var onSample: ((MotionSample) -> Void)?
    @ObservationIgnored let simulator = MotionSimulator(seed: UInt64.random(in: 1...UInt64.max))

    @ObservationIgnored private let manager = CMHeadphoneMotionManager()
    @ObservationIgnored private let queue: OperationQueue = {
        let q = OperationQueue()
        q.name = "LouVoice.motion"
        q.maxConcurrentOperationCount = 1
        return q
    }()
    @ObservationIgnored private let delegate = ConnectionDelegate()
    @ObservationIgnored private var simTimer: Timer?
    @ObservationIgnored private var captures: [Capture] = []

    private final class Capture {
        let end: Double
        var samples: [MotionSample]
        let continuation: CheckedContinuation<[MotionSample], Never>
        var done = false
        init(end: Double, samples: [MotionSample], continuation: CheckedContinuation<[MotionSample], Never>) {
            self.end = end; self.samples = samples; self.continuation = continuation
        }
    }

    var isSimulated: Bool { source == .simulator }

    func start() {
        switch source {
        case .airpods: startAirPods()
        case .simulator: startSimulator()
        }
    }

    func stop() {
        manager.stopDeviceMotionUpdates()
        manager.stopConnectionStatusUpdates()
        simTimer?.invalidate()
        simTimer = nil
        status = .idle
        sampleRate = 0
    }

    private func restart() {
        stop()
        history.removeAll()
        latest = nil
        start()
    }

    // MARK: Sources

    private func startAirPods() {
        guard manager.isDeviceMotionAvailable else { status = .unsupported; return }
        switch CMHeadphoneMotionManager.authorizationStatus() {
        case .denied, .restricted: status = .denied; return
        default: break
        }
        status = .waiting
        delegate.onChange = { [weak self] connected in
            DispatchQueue.main.async { self?.connectionChanged(connected) }
        }
        manager.delegate = delegate
        manager.startConnectionStatusUpdates()
        manager.startDeviceMotionUpdates(to: queue) { [weak self] motion, error in
            // Convert on the motion queue, hop to main for state.
            let sample = motion.map(Self.convert)
            let failure = error as NSError?
            DispatchQueue.main.async { self?.handle(sample, failure) }
        }
    }

    nonisolated private static func convert(_ m: CMDeviceMotion) -> MotionSample {
        let q = m.attitude.quaternion
        // CMDeviceMotion.sensorLocation is iOS-only, so the Mac can't tell which earbud reports (D21).
        return MotionSample(
            t: m.timestamp,
            accel: Vec3(m.userAcceleration.x, m.userAcceleration.y, m.userAcceleration.z),
            rotation: Vec3(m.rotationRate.x, m.rotationRate.y, m.rotationRate.z),
            gravity: Vec3(m.gravity.x, m.gravity.y, m.gravity.z),
            attitude: Quat(q.w, q.x, q.y, q.z),
            pitch: m.attitude.pitch, roll: m.attitude.roll, yaw: m.attitude.yaw,
            location: .unknown)
    }

    private func connectionChanged(_ connected: Bool) {
        if !connected { status = .waiting; sampleRate = 0 }
    }

    private func handle(_ sample: MotionSample?, _ error: NSError?) {
        if let error {
            status = error.domain == CMErrorDomain && error.code == Int(CMErrorMotionActivityNotAuthorized.rawValue)
                ? .denied : .error(error.localizedDescription)
            return
        }
        if let sample { ingest(sample) }
    }

    private func startSimulator() {
        status = .streaming
        simTimer = Timer.scheduledTimer(withTimeInterval: 1 / simulator.rate, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated {
                guard let self, let s = self.simulator.step() else { return }
                self.ingest(s)
            }
        }
    }

    // MARK: Ingest

    private func ingest(_ s: MotionSample) {
        status = .streaming
        if let prev = latest { maxRecentGap = max(maxRecentGap * 0.98, s.t - prev.t) }
        latest = s
        history.append(s)
        if let cut = history.firstIndex(where: { $0.t >= s.t - Self.historySeconds }), cut > 0 {
            history.removeFirst(cut)
        }
        let recent = history.suffix(50)
        if let first = recent.first, let last = recent.last, last.t > first.t {
            sampleRate = Double(recent.count - 1) / (last.t - first.t)
        }

        for c in captures where !c.done {
            c.samples.append(s)
            if s.t >= c.end { finish(c) }
        }
        captures.removeAll { $0.done }
        onSample?(s)
    }

    private func finish(_ c: Capture) {
        guard !c.done else { return }
        c.done = true
        c.continuation.resume(returning: c.samples)
    }

    /// Record `preroll` seconds already in history plus the next `window` seconds of motion.
    /// Times are on the sample clock, so Bluetooth latency doesn't shift the window.
    func capture(preroll: Double = 0.3, window: Double = 1.8) async -> [MotionSample] {
        let now = latest?.t ?? 0
        let pre = history.filter { $0.t >= now - preroll }
        return await withCheckedContinuation { continuation in
            let c = Capture(end: now + window, samples: pre, continuation: continuation)
            captures.append(c)
            // If samples stop arriving, return what we have.
            Task { @MainActor [weak self] in
                try? await Task.sleep(for: .seconds(window + 1.5))
                self?.finish(c)
                self?.captures.removeAll { $0.done }
            }
        }
    }

    /// In simulator mode, perform the movement the user was prompted for.
    func simulate(_ action: SimAction?) {
        guard isSimulated, let action else { return }
        simulator.perform(action)
    }
}

private final class ConnectionDelegate: NSObject, CMHeadphoneMotionManagerDelegate {
    var onChange: ((Bool) -> Void)?
    func headphoneMotionManagerDidConnect(_ manager: CMHeadphoneMotionManager) { onChange?(true) }
    func headphoneMotionManagerDidDisconnect(_ manager: CMHeadphoneMotionManager) { onChange?(false) }
}

import AppKit
import AVFoundation
import MediaPlayer

/// Audio cues and optional spoken prompts. Output only — no microphone (D1).
@MainActor
final class CueService {
    var speakPrompts = true
    private let synth = AVSpeechSynthesizer()

    enum Cue: String {
        case start = "Tink", end = "Pop", accept = "Glass", reject = "Basso", ready = "Purr"
    }

    func play(_ cue: Cue) {
        NSSound(named: NSSound.Name(cue.rawValue))?.play()
    }

    func say(_ text: String) {
        guard speakPrompts else { return }
        synth.stopSpeaking(at: .immediate)
        let u = AVSpeechUtterance(string: text)
        u.rate = 0.45
        synth.speak(u)
    }
}

/// AirPods stem press → capture trigger (D15). macOS routes media remote commands to the
/// "now playing" app, so while enabled we claim now-playing and keep a silent output stream
/// alive. Output only; the microphone is never opened.
@MainActor
final class StemPress {
    var onPress: (() -> Void)?
    private(set) var isEnabled = false
    private var engine: AVAudioEngine?
    private var lastPress = Date.distantPast
    private var targets: [(MPRemoteCommand, Any)] = []

    func enable() {
        guard !isEnabled else { return }
        isEnabled = true
        startSilence()
        let center = MPRemoteCommandCenter.shared()
        for command in [center.togglePlayPauseCommand, center.playCommand, center.pauseCommand] {
            command.isEnabled = true
            let token = command.addTarget { [weak self] _ in
                DispatchQueue.main.async { self?.pressed() }
                return .success
            }
            targets.append((command, token))
        }
        let info = MPNowPlayingInfoCenter.default()
        info.nowPlayingInfo = [MPMediaItemPropertyTitle: "LouVoice", MPMediaItemPropertyArtist: "Press the stem to speak"]
        info.playbackState = .playing
    }

    func disable() {
        guard isEnabled else { return }
        isEnabled = false
        for (command, token) in targets { command.removeTarget(token) }
        targets.removeAll()
        MPNowPlayingInfoCenter.default().playbackState = .stopped
        MPNowPlayingInfoCenter.default().nowPlayingInfo = nil
        engine?.stop()
        engine = nil
    }

    private func pressed() {
        // play/pause can arrive in pairs; debounce.
        guard Date().timeIntervalSince(lastPress) > 0.5 else { return }
        lastPress = Date()
        MPNowPlayingInfoCenter.default().playbackState = .playing
        onPress?()
    }

    private func startSilence() {
        let engine = AVAudioEngine()
        let format = engine.outputNode.inputFormat(forBus: 0)
        let source = AVAudioSourceNode { _, _, frameCount, buffers -> OSStatus in
            for buffer in UnsafeMutableAudioBufferListPointer(buffers) {
                memset(buffer.mData, 0, Int(buffer.mDataByteSize))
            }
            _ = frameCount
            return noErr
        }
        engine.attach(source)
        engine.connect(source, to: engine.mainMixerNode, format: format)
        do { try engine.start(); self.engine = engine } catch { self.engine = nil }
    }
}

import Foundation
import LouVoiceCore

/// One recorded capture window with its prompted (or confirmed) label.
struct Take: Codable, Identifiable, Hashable {
    var id = UUID()
    var label: String
    /// Enrollment block — one pass between re-seats. Held out as a unit in evaluation (D12).
    var block: String
    var session: String
    var createdAt = Date()
    var samples: [MotionSample]

    static func == (a: Take, b: Take) -> Bool { a.id == b.id }
    func hash(into h: inout Hasher) { h.combine(id) }
}

struct Dataset: Codable {
    var version = 1
    var vocabulary: [String]
    var takes: [Take]
    /// Median rest energy from the last calibration (quality gate, D14).
    var noiseFloor: Double?

    static let defaultVocabulary = ["yes", "no", "hello", "stop", "open", "banana", "okay", "thank you"]
    static let empty = Dataset(vocabulary: defaultVocabulary, takes: [], noiseFloor: nil)
}

/// JSON in ~/Library/Application Support/LouVoice/. Separate files per source so simulated
/// takes can never pollute real AirPods data.
enum DatasetStore {
    static var directory: URL {
        let dir = URL.applicationSupportDirectory.appending(path: "LouVoice", directoryHint: .isDirectory)
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        return dir
    }

    static func url(simulated: Bool) -> URL {
        directory.appending(path: simulated ? "dataset-simulated.json" : "dataset.json")
    }

    static func load(simulated: Bool) -> Dataset {
        guard let data = try? Data(contentsOf: url(simulated: simulated)),
              let dataset = try? JSONDecoder().decode(Dataset.self, from: data) else { return .empty }
        return dataset
    }

    static func save(_ dataset: Dataset, simulated: Bool) {
        let url = url(simulated: simulated)
        Task.detached(priority: .utility) {
            do {
                try JSONEncoder().encode(dataset).write(to: url, options: .atomic)
            } catch {
                print("LouVoice: failed to save dataset: \(error)")
            }
        }
    }
}

import AppKit
import Foundation
import LouVoiceCore
import Observation

@MainActor @Observable
final class AppModel {
    enum Screen: String, CaseIterable, Identifiable {
        case sensors = "Sensors", enroll = "Enroll", evaluate = "Evaluate", decode = "Decode"
        var id: String { rawValue }
        var symbol: String {
            switch self {
            case .sensors: "waveform.path.ecg"
            case .enroll: "list.bullet.clipboard"
            case .evaluate: "checkmark.seal"
            case .decode: "text.bubble"
            }
        }
    }

    let hub = MotionHub()
    let cues = CueService()
    let stem = StemPress()
    @ObservationIgnored private(set) lazy var enrollment = Enrollment(model: self)
    @ObservationIgnored private(set) lazy var decoder = Decoder(model: self)

    var screen: Screen = .enroll
    private(set) var dataset: Dataset
    private(set) var classifier: Classifier?
    private(set) var isTraining = false
    private(set) var evaluation: EvaluationReport?
    private(set) var isEvaluating = false
    private(set) var evaluationProgress = 0.0

    @ObservationIgnored let featureConfig = FeatureConfig()
    @ObservationIgnored private var featureCache: [UUID: SegmentFeatures] = [:]
    @ObservationIgnored private var keyMonitor: Any?
    @ObservationIgnored private var rebuildTask: Task<Void, Never>?
    @ObservationIgnored private var started = false

    init() {
        dataset = DatasetStore.load(simulated: false)
    }

    func start() {
        guard !started else { return }
        started = true
        hub.onSample = { [weak self] s in self?.decoder.ingest(s) }
        stem.onPress = { [weak self] in self?.stemPressed() }
        hub.start()
        installKeyMonitor()
        rebuildClassifier()
    }

    var isSimulated: Bool { hub.isSimulated }

    func setSource(_ source: MotionHub.Source) {
        guard source != hub.source else { return }
        enrollment.stop()
        hub.source = source
        dataset = DatasetStore.load(simulated: source == .simulator)
        featureCache.removeAll()
        evaluation = nil
        rebuildClassifier()
    }

    // MARK: Dataset

    var words: [String] { dataset.vocabulary }

    func features(for take: Take) -> SegmentFeatures? {
        if let f = featureCache[take.id] { return f }
        let f = Features.extract(take.samples, config: featureConfig)
        featureCache[take.id] = f
        return f
    }

    func addTake(_ take: Take, features: SegmentFeatures) {
        dataset.takes.append(take)
        featureCache[take.id] = features
        persist()
    }

    func deleteTakes(where predicate: (Take) -> Bool) {
        dataset.takes.removeAll(where: predicate)
        persist()
    }

    func setNoiseFloor(_ value: Double?) {
        dataset.noiseFloor = value
        DatasetStore.save(dataset, simulated: isSimulated)
    }

    func addWord(_ raw: String) {
        let word = raw.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !word.isEmpty, word != noneLabel, !dataset.vocabulary.contains(word) else { return }
        dataset.vocabulary.append(word)
        DatasetStore.save(dataset, simulated: isSimulated)
    }

    func removeWord(_ word: String) {
        dataset.vocabulary.removeAll { $0 == word }
        DatasetStore.save(dataset, simulated: isSimulated)
    }

    func takeCount(_ label: String) -> Int { dataset.takes.filter { $0.label == label }.count }
    var blocks: [String] { Array(Set(dataset.takes.map(\.block))).sorted() }

    private func persist() {
        DatasetStore.save(dataset, simulated: isSimulated)
        evaluation = nil
        rebuildClassifier()
    }

    // MARK: Training / evaluation

    func rebuildClassifier() {
        rebuildTask?.cancel()
        let training = dataset.takes.compactMap { take in
            features(for: take).map { LabeledFeatures(id: take.id.uuidString, label: take.label, features: $0.sequence) }
        }
        isTraining = true
        rebuildTask = Task { [weak self] in
            let built = await Task.detached(priority: .userInitiated) { Classifier(training: training) }.value
            guard !Task.isCancelled, let self else { return }
            self.classifier = built
            self.isTraining = false
        }
    }

    func runEvaluation() {
        guard !isEvaluating else { return }
        let takes = dataset.takes.compactMap { take in
            features(for: take).map { EvalTake(id: take.id.uuidString, label: take.label, block: take.block, features: $0.sequence) }
        }
        isEvaluating = true
        evaluationProgress = 0
        Task { [weak self] in
            let report = await Task.detached(priority: .userInitiated) {
                Evaluation.run(takes, permutations: 200) { p in
                    Task { @MainActor [weak self] in self?.evaluationProgress = p }
                }
            }.value
            self?.evaluation = report
            self?.isEvaluating = false
        }
    }

    // MARK: Input

    private func stemPressed() {
        if screen == .decode { decoder.trigger() }
        else if screen == .enroll { enrollment.continueAfterBreak() }
    }

    private func installKeyMonitor() {
        keyMonitor = NSEvent.addLocalMonitorForEvents(matching: .keyDown) { [weak self] event in
            guard let self else { return event }
            if NSApp.keyWindow?.firstResponder is NSText { return event }
            let consumed: Bool = MainActor.assumeIsolated {
                switch (event.keyCode, self.screen) {
                case (49, .decode): if !event.isARepeat { self.decoder.trigger() }; return true          // Space
                case (49, .enroll): self.enrollment.continueAfterBreak(); return true
                case (16, .decode): self.decoder.confirm(true); return true                               // Y
                case (45, .decode): self.decoder.confirm(false); return true                              // N
                default: return false
                }
            }
            return consumed ? nil : event
        }
    }
}

import Foundation
import LouVoiceCore
import Observation

/// Prompted, timed enrollment (PLAN §5): rest calibration → blocks of shuffled prompts with a
/// beep-timed capture window → quality gate with re-queue → re-seat break between blocks.
@MainActor @Observable
final class Enrollment {
    struct Prompt: Identifiable, Hashable {
        let id = UUID()
        var label: String
        var text: String
        var action: SimAction
        var attempts = 0
    }

    enum Phase: Equatable {
        case idle
        case calibrating
        case ready(Prompt)
        case recording(Prompt)
        case feedback(ok: Bool, message: String)
        case blockBreak(next: Int)
        case finished
    }

    var reps = 3
    var blockCount = 3
    var noisePerBlock = 4

    private(set) var phase: Phase = .idle
    private(set) var block = 0
    private(set) var totalBlocks = 0
    private(set) var completed = 0
    private(set) var total = 0
    private(set) var rejected = 0
    private(set) var log: [String] = []

    static let preroll = 0.3, window = 1.8, readyPause = 0.9, maxAttempts = 3

    @ObservationIgnored private unowned let model: AppModel
    @ObservationIgnored private var task: Task<Void, Never>?
    @ObservationIgnored private var breakContinuation: CheckedContinuation<Void, Never>?

    init(model: AppModel) { self.model = model }

    var isRunning: Bool { task != nil }

    /// Full enrollment of the vocabulary, or a quick "teach a new word" (one block, no noise).
    func start(words: [String], reps: Int, blocks: Int, noisePerBlock: Int, prefix: String = "enroll") {
        guard task == nil, !words.isEmpty else { return }
        let session = Self.stamp()
        totalBlocks = blocks
        total = blocks * (words.count * reps + noisePerBlock)
        completed = 0; rejected = 0; block = 0; log = []
        task = Task { [weak self] in
            await self?.run(words: words, reps: reps, blocks: blocks, noise: noisePerBlock,
                            session: session, prefix: prefix)
            self?.task = nil
        }
    }

    func stop() {
        task?.cancel()
        task = nil
        breakContinuation?.resume()
        breakContinuation = nil
        phase = .idle
    }

    func continueAfterBreak() {
        breakContinuation?.resume()
        breakContinuation = nil
    }

    private func run(words: [String], reps: Int, blocks: Int, noise: Int, session: String, prefix: String) async {
        let hub = model.hub, cues = model.cues

        if model.dataset.noiseFloor == nil || prefix == "enroll" {
            phase = .calibrating
            cues.say("Stay still for two seconds")
            try? await Task.sleep(for: .seconds(1.2))
            cues.play(.start)
            let rest = await hub.capture(preroll: 0, window: 2.0)
            cues.play(.end)
            model.setNoiseFloor(Features.noiseFloor(rest, config: model.featureConfig))
            if Task.isCancelled { return }
        }

        for b in 1...blocks {
            block = b
            if b > 1 {
                phase = .blockBreak(next: b)
                cues.say("Take out both AirPods, put them back in, then press continue")
                if hub.isSimulated { hub.simulator.reseat() }
                await withCheckedContinuation { breakContinuation = $0 }
                if Task.isCancelled { return }
            }
            let blockID = "\(prefix)-\(session)-b\(b)"
            var queue = Self.prompts(words: words, reps: reps, noise: noise).shuffled()
            while !queue.isEmpty {
                if Task.isCancelled { return }
                var prompt = queue.removeFirst()
                phase = .ready(prompt)
                cues.say(prompt.text)
                try? await Task.sleep(for: .seconds(Self.readyPause + (prompt.label == noneLabel ? 0.6 : 0)))
                if Task.isCancelled { return }

                phase = .recording(prompt)
                cues.play(.start)
                hub.simulate(prompt.action)
                let samples = await hub.capture(preroll: Self.preroll, window: Self.window)
                cues.play(.end)
                if Task.isCancelled { return }

                let isNone = prompt.label == noneLabel
                guard let features = Features.extract(samples, config: model.featureConfig) else {
                    phase = .feedback(ok: false, message: "No motion data — are the AirPods connected?")
                    try? await Task.sleep(for: .seconds(1.2))
                    queue.append(prompt)
                    continue
                }
                if let problem = Quality.check(features, noiseFloor: model.dataset.noiseFloor, isNone: isNone) {
                    rejected += 1
                    prompt.attempts += 1
                    log.insert("✗ \(prompt.text): \(problem)", at: 0)
                    phase = .feedback(ok: false, message: problem)
                    if prompt.attempts < Self.maxAttempts { queue.append(prompt) } else { completed += 1 }
                    try? await Task.sleep(for: .seconds(1.4))
                } else {
                    model.addTake(Take(label: prompt.label, block: blockID, session: session, samples: samples),
                                  features: features)
                    completed += 1
                    log.insert("✓ \(prompt.text)", at: 0)
                    phase = .feedback(ok: true, message: "Got it")
                    try? await Task.sleep(for: .seconds(0.5))
                }
            }
        }
        cues.play(.ready)
        cues.say("Enrollment done")
        phase = .finished
    }

    static func prompts(words: [String], reps: Int, noise: Int) -> [Prompt] {
        var out: [Prompt] = []
        for w in words { for _ in 0..<reps { out.append(Prompt(label: w, text: w, action: .word(w))) } }
        for kind in NoiseKind.allCases.shuffled().prefix(noise) {
            out.append(Prompt(label: noneLabel, text: kind.prompt, action: .noise(kind)))
        }
        return out
    }

    static func stamp() -> String {
        let f = DateFormatter()
        f.dateFormat = "yyyyMMdd-HHmmss"
        return f.string(from: Date())
    }
}

import Foundation
import LouVoiceCore
import Observation

/// Decode loop (PLAN §6): trigger (Space / stem / button) → beep → the same timed window as
/// enrollment → classify off the main thread → nod/shake (or Y/N) confirmation window.
@MainActor @Observable
final class Decoder {
    enum Outcome: String { case pending, confirmed, rejected, unconfirmed, discarded }

    struct Result: Identifiable {
        let id = UUID()
        var prediction: Prediction
        var outcome: Outcome
        var samples: [MotionSample]
        var features: SegmentFeatures
        var simulatedWord: String?
        var date = Date()
    }

    enum Phase: Equatable { case idle, recording, thinking, confirming(until: Date) }

    private(set) var phase: Phase = .idle
    private(set) var results: [Result] = []
    private(set) var lastGesture: HeadGesture?

    /// Context screen: only these words (plus `_none`) can be decoded. Empty = all words.
    var activeWords: Set<String> = []
    var maxScore: Double = 3.0
    var minMargin: Double = 0.0
    var speakResult = true
    var addConfirmedToTraining = true
    /// Simulator only: what the fake user mouths on the next trigger (nil = random active word).
    var simulatedWord: String?

    static let confirmSeconds = 3.0

    @ObservationIgnored private unowned let model: AppModel
    @ObservationIgnored private var detector = HeadGestureDetector()
    @ObservationIgnored private var confirmTask: Task<Void, Never>?

    init(model: AppModel) { self.model = model }

    var transcript: String {
        results.reversed().filter { $0.outcome == .confirmed || $0.outcome == .unconfirmed }
            .compactMap { $0.prediction.best?.label }.joined(separator: " ")
    }

    func clear() { results.removeAll() }

    func trigger() {
        guard phase == .idle || isConfirming, let classifier = model.classifier else { return }
        if isConfirming { finishConfirm(.unconfirmed) }
        let hub = model.hub, cues = model.cues
        phase = .recording
        Task { [weak self] in
            guard let self else { return }
            cues.play(.start)
            var simWord: String?
            if hub.isSimulated {
                let pool = self.activeWords.isEmpty ? self.model.words : Array(self.activeWords)
                simWord = self.simulatedWord ?? pool.randomElement()
                hub.simulate(simWord.map { .word($0) })
            }
            let samples = await hub.capture(preroll: Enrollment.preroll, window: Enrollment.window)
            cues.play(.end)
            self.phase = .thinking
            guard let features = Features.extract(samples, config: self.model.featureConfig) else {
                self.phase = .idle
                return
            }
            let active = self.activeWords.isEmpty ? nil : self.activeWords
            let (maxScore, minMargin) = (self.maxScore, self.minMargin)
            let prediction = await Task.detached(priority: .userInitiated) {
                classifier.predict(features.sequence, active: active, maxScore: maxScore, minMargin: minMargin)
            }.value

            var result = Result(prediction: prediction, outcome: .pending, samples: samples,
                                features: features, simulatedWord: simWord)
            if prediction.accepted, let word = prediction.best?.label {
                if self.speakResult { cues.say(word) }
                self.results.insert(result, at: 0)
                self.startConfirm()
            } else {
                result.outcome = .discarded
                self.results.insert(result, at: 0)
                cues.play(.reject)
                self.phase = .idle
            }
        }
    }

    var isConfirming: Bool { if case .confirming = phase { true } else { false } }

    private func startConfirm() {
        detector.reset()
        lastGesture = nil
        phase = .confirming(until: Date().addingTimeInterval(Self.confirmSeconds))
        confirmTask?.cancel()
        confirmTask = Task { [weak self] in
            try? await Task.sleep(for: .seconds(Self.confirmSeconds))
            guard !Task.isCancelled else { return }
            self?.finishConfirm(.unconfirmed)
        }
    }

    /// Y/N keys or nod/shake.
    func confirm(_ yes: Bool) {
        guard isConfirming else { return }
        finishConfirm(yes ? .confirmed : .rejected)
    }

    /// Every motion sample passes through here; gestures only count during confirmation.
    func ingest(_ s: MotionSample) {
        guard isConfirming else { return }
        if let g = detector.push(s) {
            lastGesture = g
            confirm(g == .nod)
        }
    }

    /// Simulator buttons.
    func simulateGesture(_ g: HeadGesture) {
        model.hub.simulate(g == .nod ? .nod : .shake)
    }

    private func finishConfirm(_ outcome: Outcome) {
        confirmTask?.cancel()
        confirmTask = nil
        phase = .idle
        guard let i = results.firstIndex(where: { $0.outcome == .pending }) else { return }
        results[i].outcome = outcome
        switch outcome {
        case .confirmed:
            model.cues.play(.accept)
            let r = results[i]
            if addConfirmedToTraining, let label = r.prediction.best?.label {
                // Confirmed decodes become training data (D15), in their own daily block.
                let day = String(Enrollment.stamp().prefix(8))
                model.addTake(Take(label: label, block: "confirmed-\(day)", session: day, samples: r.samples),
                              features: r.features)
            }
        case .rejected:
            model.cues.play(.reject)
        default:
            break
        }
    }
}

