import AppKit
import Foundation
import LouVoiceCore
import Observation

/// Capture timing (D13). Changing it affects new takes only.
struct CaptureSettings: Codable, Hashable {
    var preroll = 0.3
    var window = 1.8
}

@MainActor @Observable
final class AppModel {
    enum Screen: String, CaseIterable, Identifiable {
        case sensors = "Sensors", enroll = "Enroll", evaluate = "Evaluate", tune = "Tune", decode = "Decode"
        var id: String { rawValue }
        var symbol: String {
            switch self {
            case .sensors: "waveform.path.ecg"
            case .enroll: "list.bullet.clipboard"
            case .evaluate: "checkmark.seal"
            case .tune: "slider.horizontal.3"
            case .decode: "text.bubble"
            }
        }
    }

    let hub = MotionHub()
    let cues = CueService()
    let stem = StemPress()
    @ObservationIgnored private(set) lazy var enrollment = Enrollment(model: self)
    @ObservationIgnored private(set) lazy var decoder = Decoder(model: self)

    var screen: Screen = .enroll
    private(set) var dataset: Dataset
    private(set) var classifier: Classifier?
    private(set) var isTraining = false
    private(set) var evaluation: EvaluationReport?
    private(set) var quizScore: (correct: Int, total: Int, perLabel: [String: (Int, Int)])?
    private(set) var isEvaluating = false
    private(set) var evaluationProgress = 0.0

    /// Pipeline variables (Tune screen). Changing them re-extracts features and retrains.
    private(set) var config: PipelineConfig
    var capture: CaptureSettings { didSet { Self.store(capture, key: Self.captureKey) } }

    // Auto-tune state.
    private(set) var tuneTrials: [Tuner.Trial] = []
    private(set) var isTuning = false
    private(set) var tuneProgress = 0.0
    private(set) var tuneStatus = ""

    @ObservationIgnored private var featureCache: [UUID: SegmentFeatures] = [:]
    @ObservationIgnored private var keyMonitor: Any?
    @ObservationIgnored private var rebuildTask: Task<Void, Never>?
    @ObservationIgnored private var started = false

    static let configKey = "pipelineConfig.v1", captureKey = "captureSettings.v1"

    init() {
        // --smoke (and LOUVOICE_SOURCE=simulator) start on the simulator without touching CoreMotion.
        let simulated = CommandLine.arguments.contains("--smoke")
            || ProcessInfo.processInfo.environment["LOUVOICE_SOURCE"] == "simulator"
        if simulated { hub.source = .simulator }
        dataset = DatasetStore.load(simulated: simulated)
        let isolated = ProcessInfo.processInfo.environment["LOUVOICE_DATA_DIR"] != nil
        config = isolated ? .defaults : (Self.load(PipelineConfig.self, key: Self.configKey) ?? .defaults)
        capture = isolated ? CaptureSettings() : (Self.load(CaptureSettings.self, key: Self.captureKey) ?? CaptureSettings())
    }

    func start() {
        guard !started else { return }
        started = true
        hub.onSample = { [weak self] s in self?.decoder.ingest(s) }
        stem.onPress = { [weak self] in self?.stemPressed() }
        if CommandLine.arguments.contains("--smoke") { SmokeTest(model: self).run() }
        hub.start()
        installKeyMonitor()
        rebuildClassifier()
    }

    var isSimulated: Bool { hub.isSimulated }

    func setSource(_ source: MotionHub.Source) {
        guard source != hub.source else { return }
        enrollment.stop()
        hub.source = source
        dataset = DatasetStore.load(simulated: source == .simulator)
        featureCache.removeAll()
        clearResults()
        rebuildClassifier()
    }

    // MARK: Config

    func setConfig(_ new: PipelineConfig) {
        guard new != config else { return }
        if new.features != config.features { featureCache.removeAll() }
        config = new
        Self.store(config, key: Self.configKey)
        clearResults()
        rebuildClassifier()
    }

    func updateConfig(_ change: (inout PipelineConfig) -> Void) {
        var c = config
        change(&c)
        setConfig(c)
    }

    private func clearResults() {
        evaluation = nil
        quizScore = nil
    }

    // MARK: Dataset

    var words: [String] { dataset.vocabulary }

    func features(for take: Take) -> SegmentFeatures? {
        if let f = featureCache[take.id] { return f }
        let f = Features.extract(take.samples, config: config.features)
        featureCache[take.id] = f
        return f
    }

    func addTake(_ take: Take, features: SegmentFeatures) {
        dataset.takes.append(take)
        featureCache[take.id] = features
        persist(retrain: !take.isTest)
    }

    func deleteTakes(where predicate: (Take) -> Bool) {
        dataset.takes.removeAll(where: predicate)
        persist()
    }

    /// Quiz takes become training data (more data is the biggest lever with ~9 takes per word).
    func promoteQuizTakes() {
        for i in dataset.takes.indices where dataset.takes[i].isTest { dataset.takes[i].isTest = false }
        persist()
    }

    func setNoiseFloor(_ value: Double?) {
        dataset.noiseFloor = value
        DatasetStore.save(dataset, simulated: isSimulated)
    }

    func addWord(_ raw: String) {
        let word = raw.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !word.isEmpty, word != noneLabel, !dataset.vocabulary.contains(word) else { return }
        dataset.vocabulary.append(word)
        DatasetStore.save(dataset, simulated: isSimulated)
    }

    func removeWord(_ word: String) {
        dataset.vocabulary.removeAll { $0 == word }
        DatasetStore.save(dataset, simulated: isSimulated)
    }

    func takeCount(_ label: String) -> Int { dataset.trainingTakes.filter { $0.label == label }.count }
    var blocks: [String] { Array(Set(dataset.takes.map(\.block))).sorted() }

    private func persist(retrain: Bool = true) {
        DatasetStore.save(dataset, simulated: isSimulated)
        clearResults()
        if retrain { rebuildClassifier() }
    }

    // MARK: Training / evaluation

    func trainingFeatures(excludingBlock block: String? = nil) -> [LabeledFeatures] {
        dataset.trainingTakes.filter { $0.block != block }.compactMap { take in
            features(for: take).map { LabeledFeatures(id: take.id.uuidString, label: take.label, features: $0.sequence) }
        }
    }

    func rebuildClassifier() {
        rebuildTask?.cancel()
        let training = trainingFeatures()
        let classifierConfig = config.classifier
        isTraining = true
        rebuildTask = Task { [weak self] in
            let built = await Task.detached(priority: .userInitiated) { Classifier(training: training, config: classifierConfig) }.value
            guard !Task.isCancelled, let self else { return }
            self.classifier = built
            self.isTraining = false
        }
    }

    func runEvaluation() {
        guard !isEvaluating else { return }
        let takes = dataset.trainingTakes.compactMap { take in
            features(for: take).map { EvalTake(id: take.id.uuidString, label: take.label, block: take.block, features: $0.sequence) }
        }
        let training = dataset.trainingTakes.map(Tuner.RawTake.init)
        let tests = dataset.testTakes.map(Tuner.RawTake.init)
        let config = config
        isEvaluating = true
        evaluationProgress = 0
        let box = WeakModel(self)
        Task { [weak self] in
            let (report, quiz) = await Task.detached(priority: .userInitiated) {
                let r = Evaluation.run(takes, config: config.classifier, permutations: 200) { p in
                    Task { @MainActor in box.model?.evaluationProgress = p }
                }
                let q = tests.isEmpty ? nil : Tuner.heldOut(training: training, test: tests, config: config)
                return (r, q)
            }.value
            self?.evaluation = report
            self?.quizScore = quiz
            self?.isEvaluating = false
        }
    }

    // MARK: Auto-tune

    func runAutoTune() {
        guard !isTuning else { return }
        let takes = dataset.trainingTakes.map(Tuner.RawTake.init)
        let base = config
        isTuning = true
        tuneProgress = 0
        tuneStatus = "Starting…"
        let box = WeakModel(self)
        Task { [weak self] in
            let trials = await Task.detached(priority: .userInitiated) {
                Tuner.autoTune(takes, base: base) { p, status in
                    Task { @MainActor in box.model?.tuneProgress = p; box.model?.tuneStatus = status }
                }
            }.value
            self?.tuneTrials = trials
            self?.isTuning = false
            self?.tuneStatus = trials.isEmpty ? "Not enough data (need 2+ blocks)" : "Tried \(trials.count) settings"
        }
    }

    // MARK: Input

    private func stemPressed() {
        if screen == .decode { decoder.trigger() }
        else if screen == .enroll { enrollment.continueAfterBreak() }
    }

    private func installKeyMonitor() {
        keyMonitor = NSEvent.addLocalMonitorForEvents(matching: .keyDown) { [weak self] event in
            guard let self else { return event }
            if NSApp.keyWindow?.firstResponder is NSText { return event }
            let consumed: Bool = MainActor.assumeIsolated {
                switch (event.keyCode, self.screen) {
                case (49, .decode): if !event.isARepeat { self.decoder.trigger() }; return true          // Space
                case (49, .enroll): self.enrollment.continueAfterBreak(); return true
                case (16, .decode): self.decoder.confirm(true); return true                               // Y
                case (45, .decode): self.decoder.confirm(false); return true                              // N
                default: return false
                }
            }
            return consumed ? nil : event
        }
    }

    // MARK: Persistence of settings

    private static func load<T: Decodable>(_ type: T.Type, key: String) -> T? {
        guard let data = UserDefaults.standard.data(forKey: key) else { return nil }
        return try? JSONDecoder().decode(T.self, from: data)
    }

    private static func store<T: Encodable>(_ value: T, key: String) {
        guard ProcessInfo.processInfo.environment["LOUVOICE_DATA_DIR"] == nil,
              let data = try? JSONEncoder().encode(value) else { return }
        UserDefaults.standard.set(data, forKey: key)
    }
}

/// Lets a background progress callback reach the main-actor model without capturing it.
private final class WeakModel: @unchecked Sendable {
    weak var model: AppModel?
    init(_ model: AppModel) { self.model = model }
}

import Foundation
import LouVoiceCore
import Observation

/// Prompted, timed enrollment (PLAN §5) with continuous accuracy testing (D31):
/// - **Test-then-train:** before a take is stored, the model built from the *other* blocks
///   predicts it. Every take is therefore an honest test, and accuracy updates live.
/// - **Quiz rounds:** optional test-only prompts after each block (or on their own) against the
///   model trained on everything so far. Quiz takes are saved with `isTest` and never trained on.
@MainActor @Observable
final class Enrollment {
    enum Mode: String { case train, quiz }

    struct Prompt: Identifiable, Hashable {
        let id = UUID()
        var label: String
        var text: String
        var action: SimAction
        var attempts = 0
    }

    struct LiveResult: Identifiable {
        let id = UUID()
        var label: String
        var predicted: String
        var isQuiz: Bool
        var block: Int
        var correct: Bool { label == predicted }
    }

    enum Phase: Equatable {
        case idle
        case calibrating
        case ready(Prompt, quiz: Bool)
        case recording(Prompt, quiz: Bool)
        case feedback(ok: Bool, message: String, heard: String?, correct: Bool?)
        case blockBreak(next: Int)
        case quizIntro
        case finished
    }

    var reps = 3
    var blockCount = 3
    var noisePerBlock = 4
    var quizAfterBlock = true

    private(set) var mode: Mode = .train
    private(set) var phase: Phase = .idle
    private(set) var block = 0
    private(set) var totalBlocks = 0
    private(set) var completed = 0
    private(set) var total = 0
    private(set) var rejected = 0
    private(set) var log: [String] = []
    private(set) var results: [LiveResult] = []

    static let readyPause = 0.9, maxAttempts = 3

    @ObservationIgnored private unowned let model: AppModel
    @ObservationIgnored private var task: Task<Void, Never>?
    @ObservationIgnored private var breakContinuation: CheckedContinuation<Void, Never>?

    init(model: AppModel) { self.model = model }

    var isRunning: Bool { task != nil }

    // MARK: Live scores

    struct Score { var correct = 0, total = 0; var rate: Double? { total == 0 ? nil : Double(correct) / Double(total) } }

    func score(quiz: Bool?, label: String? = nil, last: Int? = nil) -> Score {
        var rs = results.filter { (quiz == nil || $0.isQuiz == quiz!) && (label == nil || $0.label == label!) }
        if let last { rs = Array(rs.suffix(last)) }
        return Score(correct: rs.filter(\.correct).count, total: rs.count)
    }

    /// Per-block honest accuracy, to see whether more data is helping.
    func blockScores() -> [(block: Int, test: Score, quiz: Score)] {
        Set(results.map(\.block)).sorted().map { b in
            let t = results.filter { $0.block == b && !$0.isQuiz }, q = results.filter { $0.block == b && $0.isQuiz }
            return (b, Score(correct: t.filter(\.correct).count, total: t.count),
                    Score(correct: q.filter(\.correct).count, total: q.count))
        }
    }

    // MARK: Control

    /// Training enrollment, a quick "teach a new word" (one block, no noise), or a quiz.
    func start(words: [String], reps: Int, blocks: Int, noisePerBlock: Int, prefix: String = "enroll", mode: Mode = .train) {
        guard task == nil, !words.isEmpty else { return }
        let session = Self.stamp()
        self.mode = mode
        let quizzes = mode == .train && quizAfterBlock
        totalBlocks = blocks
        total = blocks * (words.count * reps + noisePerBlock) + (quizzes ? blocks * words.count : 0)
        completed = 0; rejected = 0; block = 0; log = []; results = []
        task = Task { [weak self] in
            await self?.run(words: words, reps: reps, blocks: blocks, noise: noisePerBlock,
                            session: session, prefix: prefix, quizzes: quizzes)
            self?.task = nil
        }
    }

    func startQuiz(words: [String], reps: Int) {
        start(words: words, reps: reps, blocks: 1, noisePerBlock: 0, prefix: "quiz", mode: .quiz)
    }

    func stop() {
        task?.cancel()
        task = nil
        breakContinuation?.resume()
        breakContinuation = nil
        phase = .idle
    }

    func continueAfterBreak() {
        breakContinuation?.resume()
        breakContinuation = nil
    }

    // MARK: Flow

    private func run(words: [String], reps: Int, blocks: Int, noise: Int, session: String, prefix: String, quizzes: Bool) async {
        let hub = model.hub, cues = model.cues

        if mode == .train, model.dataset.noiseFloor == nil || prefix == "enroll" {
            phase = .calibrating
            cues.say("Stay still for two seconds")
            try? await Task.sleep(for: .seconds(1.2))
            cues.play(.start)
            let rest = await hub.capture(preroll: 0, window: 2.0)
            cues.play(.end)
            model.setNoiseFloor(Features.noiseFloor(rest, config: model.config.features))
            if Task.isCancelled { return }
        }

        for b in 1...blocks {
            block = b
            if b > 1 {
                phase = .blockBreak(next: b)
                cues.say("Take out both AirPods, put them back in, then press continue")
                if hub.isSimulated { hub.simulator.reseat() }
                await withCheckedContinuation { breakContinuation = $0 }
                if Task.isCancelled { return }
            }

            if mode == .quiz {
                let classifier = await buildClassifier(excluding: nil)
                await runPrompts(Self.prompts(words: words, reps: reps, noise: 0).shuffled(), block: b,
                                 blockID: "quiz-\(session)", session: session, quiz: true, classifier: classifier)
                continue
            }

            // Test-then-train: predict each new take with a model that has never seen this block.
            let blockID = "\(prefix)-\(session)-b\(b)"
            let honest = await buildClassifier(excluding: blockID)
            await runPrompts(Self.prompts(words: words, reps: reps, noise: noise).shuffled(), block: b,
                             blockID: blockID, session: session, quiz: false, classifier: honest)
            if Task.isCancelled { return }

            if quizzes {
                phase = .quizIntro
                cues.say("Quick quiz. These takes are only for testing")
                try? await Task.sleep(for: .seconds(1.6))
                let classifier = await buildClassifier(excluding: nil)
                await runPrompts(Self.prompts(words: words, reps: 1, noise: 0).shuffled(), block: b,
                                 blockID: "quiz-\(session)-b\(b)", session: session, quiz: true, classifier: classifier)
            }
        }
        if Task.isCancelled { return }
        cues.play(.ready)
        cues.say(mode == .quiz ? "Quiz done" : "Enrollment done")
        phase = .finished
    }

    private func buildClassifier(excluding block: String?) async -> Classifier? {
        let training = model.trainingFeatures(excludingBlock: block)
        let config = model.config.classifier
        return await Task.detached(priority: .userInitiated) { Classifier(training: training, config: config) }.value
    }

    private func runPrompts(_ prompts: [Prompt], block b: Int, blockID: String, session: String,
                            quiz: Bool, classifier: Classifier?) async {
        let hub = model.hub, cues = model.cues
        var queue = prompts
        while !queue.isEmpty {
            if Task.isCancelled { return }
            var prompt = queue.removeFirst()
            phase = .ready(prompt, quiz: quiz)
            cues.say(prompt.text)
            try? await Task.sleep(for: .seconds(Self.readyPause + (prompt.label == noneLabel ? 0.6 : 0)))
            if Task.isCancelled { return }

            phase = .recording(prompt, quiz: quiz)
            cues.play(.start)
            hub.simulate(prompt.action)
            let samples = await hub.capture(preroll: model.capture.preroll, window: model.capture.window)
            cues.play(.end)
            if Task.isCancelled { return }

            let isNone = prompt.label == noneLabel
            guard let features = Features.extract(samples, config: model.config.features) else {
                phase = .feedback(ok: false, message: "No motion data — are the AirPods connected?", heard: nil, correct: nil)
                try? await Task.sleep(for: .seconds(1.2))
                queue.append(prompt)
                continue
            }
            if let problem = Quality.check(features, noiseFloor: model.dataset.noiseFloor, isNone: isNone) {
                rejected += 1
                prompt.attempts += 1
                log.insert("✗ \(prompt.text): \(problem)", at: 0)
                phase = .feedback(ok: false, message: problem, heard: nil, correct: nil)
                if prompt.attempts < Self.maxAttempts { queue.append(prompt) } else { completed += 1 }
                try? await Task.sleep(for: .seconds(1.4))
                continue
            }

            // Test before train.
            var heard: String?
            if let classifier {
                let seq = features.sequence
                heard = await Task.detached(priority: .userInitiated) { classifier.predict(seq).best?.label }.value
            }
            if let heard {
                results.append(LiveResult(label: prompt.label, predicted: heard, isQuiz: quiz, block: b))
            }
            model.addTake(Take(label: prompt.label, block: blockID, session: session, samples: samples, isTest: quiz),
                          features: features)
            completed += 1
            let mark = heard.map { $0 == prompt.label ? "✓" : "✗ heard \(displayLabel($0))" } ?? "(no model yet)"
            log.insert("\(quiz ? "quiz" : "take") \(displayLabel(prompt.label)): \(mark)", at: 0)
            phase = .feedback(ok: true, message: quiz ? "Quiz take saved" : "Got it",
                              heard: heard, correct: heard.map { $0 == prompt.label })
            try? await Task.sleep(for: .seconds(heard == nil ? 0.5 : 0.9))
        }
    }

    static func prompts(words: [String], reps: Int, noise: Int) -> [Prompt] {
        var out: [Prompt] = []
        for w in words { for _ in 0..<reps { out.append(Prompt(label: w, text: w, action: .word(w))) } }
        for kind in NoiseKind.allCases.shuffled().prefix(noise) {
            out.append(Prompt(label: noneLabel, text: kind.prompt, action: .noise(kind)))
        }
        return out
    }

    static func stamp() -> String {
        let f = DateFormatter()
        f.dateFormat = "yyyyMMdd-HHmmss"
        return f.string(from: Date())
    }
}

import LouVoiceCore
import SwiftUI

struct EnrollView: View {
    @Environment(AppModel.self) private var model
    @State private var newWord = ""
    @State private var teachWord = ""
    @State private var quizReps = 2

    var body: some View {
        let e = model.enrollment
        HStack(alignment: .top, spacing: 0) {
            ScrollView { settings.padding(16) }
                .frame(width: 300)
            Divider()
            VStack(spacing: 14) {
                PromptCard(phase: e.phase)
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                if e.isRunning || e.phase == .finished {
                    VStack(alignment: .leading, spacing: 6) {
                        ProgressView(value: Double(e.completed), total: Double(max(e.total, 1)))
                        Text("\(e.mode == .quiz ? "Quiz" : "Block \(e.block) of \(e.totalBlocks)") · \(e.completed)/\(e.total) prompts · \(e.rejected) re-takes")
                            .font(.caption).foregroundStyle(.secondary)
                    }
                }
                if !e.log.isEmpty {
                    ScrollView {
                        VStack(alignment: .leading, spacing: 2) {
                            ForEach(Array(e.log.prefix(30).enumerated()), id: \.offset) { _, line in
                                Text(line).font(.caption.monospaced()).foregroundStyle(.secondary)
                                    .frame(maxWidth: .infinity, alignment: .leading)
                            }
                        }
                    }
                    .frame(height: 90)
                }
            }
            .padding(20)
            Divider()
            ScrollView { LiveAccuracyPanel().padding(16) }
                .frame(width: 260)
        }
        .navigationTitle("Enroll")
    }

    @ViewBuilder private var settings: some View {
        @Bindable var e = model.enrollment
        let canRecord = model.hub.status == .streaming && !e.isRunning
        VStack(alignment: .leading, spacing: 16) {
            SectionCard(title: "Vocabulary") {
                ForEach(model.words, id: \.self) { word in
                    HStack {
                        Text(word)
                        Spacer()
                        Text("\(model.takeCount(word))").foregroundStyle(.secondary).monospacedDigit()
                        Button { model.removeWord(word) } label: { Image(systemName: "minus.circle") }
                            .buttonStyle(.borderless).disabled(e.isRunning)
                    }
                }
                HStack {
                    Text("(not a word)").foregroundStyle(.secondary)
                    Spacer()
                    Text("\(model.takeCount(noneLabel))").foregroundStyle(.secondary).monospacedDigit()
                }
                HStack {
                    TextField("Add word", text: $newWord).onSubmit(addWord)
                    Button("Add", action: addWord).disabled(newWord.isEmpty)
                }
                Text("Numbers are training takes. Words with different syllable counts and jaw openings are easiest.")
                    .font(.caption).foregroundStyle(.secondary)
            }
            SectionCard(title: "Training session") {
                Stepper("Blocks: \(e.blockCount)", value: $e.blockCount, in: 1...6)
                Stepper("Reps per word per block: \(e.reps)", value: $e.reps, in: 1...6)
                Stepper("Non-word prompts per block: \(e.noisePerBlock)", value: $e.noisePerBlock, in: 0...6)
                Toggle("Quiz after each block", isOn: $e.quizAfterBlock)
                Toggle("Speak prompts in AirPods", isOn: Binding(get: { model.cues.speakPrompts },
                                                                set: { model.cues.speakPrompts = $0 }))
                let prompts = e.blockCount * (model.words.count * (e.reps + (e.quizAfterBlock ? 1 : 0)) + e.noisePerBlock)
                Text("≈ \(max(1, Int(Double(prompts) * 4.4 / 60))) min. Every take is tested before it's learned.")
                    .font(.caption).foregroundStyle(.secondary)
                if e.isRunning {
                    Button("Stop", role: .destructive) { e.stop() }
                } else {
                    Button("Start training") {
                        e.start(words: model.words, reps: e.reps, blocks: e.blockCount, noisePerBlock: e.noisePerBlock)
                    }
                    .buttonStyle(.borderedProminent)
                    .disabled(!canRecord || model.words.isEmpty)
                }
            }
            SectionCard(title: "Quiz only (test, no training)") {
                Stepper("Reps per word: \(quizReps)", value: $quizReps, in: 1...5)
                Button("Run quiz") { e.startQuiz(words: model.words, reps: quizReps) }
                    .disabled(!canRecord || model.classifier == nil)
                Text("Measures the current model on fresh takes it has never seen. Re-seat first for the honest number.")
                    .font(.caption).foregroundStyle(.secondary)
            }
            SectionCard(title: "Teach a new word") {
                HStack {
                    TextField("Word", text: $teachWord)
                    Button("Teach (3 takes)") {
                        let word = teachWord.trimmingCharacters(in: .whitespaces).lowercased()
                        model.addWord(word)
                        e.start(words: [word], reps: 3, blocks: 1, noisePerBlock: 0, prefix: "teach")
                        teachWord = ""
                    }
                    .disabled(teachWord.isEmpty || !canRecord)
                }
            }
        }
    }

    private func addWord() {
        model.addWord(newWord)
        newWord = ""
    }
}

/// Live accuracy while training: test-then-train results and quiz results.
private struct LiveAccuracyPanel: View {
    @Environment(AppModel.self) private var model

    var body: some View {
        let e = model.enrollment
        VStack(alignment: .leading, spacing: 14) {
            Text("Live accuracy").font(.headline)
            if e.results.isEmpty {
                Text("Each take is predicted by a model that hasn't seen this block before it's saved. Scores appear from block 2 (or right away if you already have data).")
                    .font(.caption).foregroundStyle(.secondary)
            } else {
                let t = e.score(quiz: false), q = e.score(quiz: true), last = e.score(quiz: nil, last: 10)
                MetricTile(title: "Test-then-train", value: percent(t.rate), detail: "\(t.correct)/\(t.total) takes, unseen block")
                MetricTile(title: "Quiz", value: percent(q.rate), detail: "\(q.correct)/\(q.total) test-only takes")
                MetricTile(title: "Last 10", value: percent(last.rate), detail: "Rolling")

                VStack(alignment: .leading, spacing: 4) {
                    Text("Per word").font(.subheadline.weight(.semibold))
                    ForEach(model.words + [noneLabel], id: \.self) { word in
                        let s = e.score(quiz: nil, label: word)
                        if s.total > 0 {
                            HStack {
                                Text(displayLabel(word)).frame(width: 90, alignment: .leading)
                                AccuracyBar(rate: s.rate ?? 0)
                                Text("\(s.correct)/\(s.total)").font(.caption.monospacedDigit()).foregroundStyle(.secondary)
                                    .frame(width: 36, alignment: .trailing)
                            }
                        }
                    }
                }
                let blocks = e.blockScores()
                if blocks.count > 1 {
                    VStack(alignment: .leading, spacing: 4) {
                        Text("By block (is more data helping?)").font(.subheadline.weight(.semibold))
                        ForEach(blocks, id: \.block) { b in
                            HStack {
                                Text("Block \(b.block)")
                                Spacer()
                                Text("test \(percent(b.test.rate))  quiz \(percent(b.quiz.rate))")
                                    .font(.caption.monospacedDigit()).foregroundStyle(.secondary)
                            }
                        }
                    }
                }
            }
        }
    }
}

struct AccuracyBar: View {
    var rate: Double
    var body: some View {
        GeometryReader { g in
            ZStack(alignment: .leading) {
                RoundedRectangle(cornerRadius: 3).fill(Color.secondary.opacity(0.12))
                RoundedRectangle(cornerRadius: 3)
                    .fill(rate >= 0.9 ? Color.green : rate >= 0.7 ? Color.orange : Color.red)
                    .frame(width: g.size.width * rate)
            }
        }
        .frame(height: 10)
    }
}

private struct PromptCard: View {
    @Environment(AppModel.self) private var model
    var phase: Enrollment.Phase

    var body: some View {
        VStack(spacing: 14) {
            switch phase {
            case .idle:
                Image(systemName: "airpodspro").font(.system(size: 54)).foregroundStyle(.secondary)
                Text("Ready to train").font(.title2.weight(.semibold))
                coaching
            case .calibrating:
                Text("Stay still").font(.system(size: 54, weight: .bold, design: .rounded))
                Text("Measuring the resting noise floor…").foregroundStyle(.secondary)
            case .ready(let p, let quiz):
                quizTag(quiz)
                Text(p.text).font(.system(size: p.label == noneLabel ? 36 : 72, weight: .bold, design: .rounded))
                Text("Get ready… mouth it after the beep").foregroundStyle(.secondary)
            case .recording(let p, let quiz):
                quizTag(quiz)
                Text(p.text).font(.system(size: p.label == noneLabel ? 36 : 72, weight: .bold, design: .rounded))
                Label("Now", systemImage: "record.circle.fill").font(.title2).foregroundStyle(.red)
            case .feedback(let ok, let message, let heard, let correct):
                Image(systemName: !ok ? "exclamationmark.triangle.fill" : correct == false ? "xmark.circle.fill" : "checkmark.circle.fill")
                    .font(.system(size: 54)).foregroundStyle(!ok ? .orange : correct == false ? .red : .green)
                Text(message).font(.title3).multilineTextAlignment(.center)
                if let heard {
                    Text("Model heard: \(displayLabel(heard))").font(.title2.weight(.semibold))
                        .foregroundStyle(correct == true ? .green : .red)
                }
                if !ok { Text("This prompt will come back later in the block.").foregroundStyle(.secondary) }
            case .quizIntro:
                Image(systemName: "questionmark.circle.fill").font(.system(size: 54)).foregroundStyle(.blue)
                Text("Quick quiz").font(.title.weight(.semibold))
                Text("One take per word, tested against everything learned so far. Not used for training.")
                    .multilineTextAlignment(.center).foregroundStyle(.secondary)
            case .blockBreak(let next):
                Image(systemName: "arrow.triangle.2.circlepath").font(.system(size: 54)).foregroundStyle(.blue)
                Text("Re-seat your AirPods").font(.title.weight(.semibold))
                Text("Take both out, put them back in, then continue to block \(next).\nThis is what makes the accuracy number honest.")
                    .multilineTextAlignment(.center).foregroundStyle(.secondary)
                Button("Continue (Space or stem)") { model.enrollment.continueAfterBreak() }
                    .buttonStyle(.borderedProminent).keyboardShortcut(.defaultAction)
            case .finished:
                Image(systemName: "checkmark.seal.fill").font(.system(size: 54)).foregroundStyle(.green)
                Text(model.enrollment.mode == .quiz ? "Quiz complete" : "Training complete").font(.title.weight(.semibold))
                HStack {
